-- Phase 13 Part 3: support access approved by the organisation.
-- Generated by prisma migrate diff, followed by a hand-written section.

-- CreateEnum
CREATE TYPE "SupportAccessStatus" AS ENUM ('REQUESTED', 'APPROVED', 'DENIED', 'REVOKED');

-- CreateTable
CREATE TABLE "support_access" (
    "id" UUID NOT NULL,
    "organisation_id" UUID NOT NULL,
    "requested_by_user_id" UUID NOT NULL,
    "reason" TEXT NOT NULL,
    "hours" INTEGER NOT NULL,
    "status" "SupportAccessStatus" NOT NULL DEFAULT 'REQUESTED',
    "decided_by_user_id" UUID,
    "decided_at" TIMESTAMPTZ(3),
    "starts_at" TIMESTAMPTZ(3),
    "ends_at" TIMESTAMPTZ(3),
    "revoked_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "support_access_pkey" PRIMARY KEY ("id")
);

