-- AddForeignKey
ALTER TABLE "support_access" ADD CONSTRAINT "support_access_decided_by_user_id_fkey" FOREIGN KEY ("decided_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- =============================================================================================
-- Hand-written below this line: support access is requested only by a platform administrator,
-- through app_support_request() (a reason, 1-24 hours), and decided by someone else in the
-- organisation: REQUESTED -> APPROVED (the window starts now) or DENIED; APPROVED -> REVOKED.
-- Times and deciders are set by the database; every step is in the organisation's audit log.
-- The requester sees their own requests; the organisation sees all of its own. See
-- docs/security/ACCESS_CONTROL.md section 6.4c.
-- =============================================================================================

ALTER TABLE "support_access" ADD CONSTRAINT "support_access_shape"
  CHECK ("reason" = btrim("reason") AND length("reason") BETWEEN 1 AND 500
         AND "hours" BETWEEN 1 AND 24
         AND ("status" IN ('APPROVED', 'DENIED', 'REVOKED')) = ("decided_at" IS NOT NULL)
         AND ("status" IN ('APPROVED', 'REVOKED')) = ("starts_at" IS NOT NULL)
         AND ("starts_at" IS NULL) = ("ends_at" IS NULL)
         AND ("status" = 'REVOKED') = ("revoked_at" IS NOT NULL));

CREATE FUNCTION app_support_access_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'REQUESTED' THEN
      RAISE EXCEPTION 'support access starts as a request' USING ERRCODE = 'check_violation';
    END IF;
    NEW."decided_by_user_id" := NULL;
    NEW."decided_at" := NULL;
    NEW."starts_at" := NULL;
    NEW."ends_at" := NULL;
    NEW."revoked_at" := NULL;
    NEW."created_at" := now();
    RETURN NEW;
  END IF;
  IF (NEW."organisation_id", NEW."requested_by_user_id", NEW."reason", NEW."hours", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."requested_by_user_id", OLD."reason", OLD."hours", OLD."created_at") THEN
    RAISE EXCEPTION 'a support request never changes' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = OLD."status" THEN
    RAISE EXCEPTION 'nothing to change' USING ERRCODE = 'check_violation';
  END IF;
  transition := OLD."status" || '>' || NEW."status";
  IF transition NOT IN ('REQUESTED>APPROVED', 'REQUESTED>DENIED', 'APPROVED>REVOKED') THEN
    RAISE EXCEPTION 'support access cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  IF app_current_user_id() IS NULL OR app_current_user_id() = OLD."requested_by_user_id" THEN
    RAISE EXCEPTION 'support access is decided by the organisation, not the requester'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW."status" IN ('APPROVED', 'DENIED') THEN
    NEW."decided_by_user_id" := app_current_user_id();
    NEW."decided_at" := now();
    NEW."starts_at" := CASE WHEN NEW."status" = 'APPROVED' THEN now() END;
    NEW."ends_at" := CASE WHEN NEW."status" = 'APPROVED' THEN now() + make_interval(hours => OLD."hours") END;
    NEW."revoked_at" := NULL;
  ELSE
    NEW."decided_by_user_id" := OLD."decided_by_user_id";
    NEW."decided_at" := OLD."decided_at";
    NEW."starts_at" := OLD."starts_at";
    NEW."ends_at" := least(OLD."ends_at", now());
    NEW."revoked_at" := now();
  END IF;
  NEW."updated_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "support_access_guard"
  BEFORE INSERT OR UPDATE ON "support_access"
  FOR EACH ROW EXECUTE FUNCTION app_support_access_guard();

CREATE FUNCTION app_support_access_audit() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  INSERT INTO "audit_logs" ("id", "organisation_id", "actor_user_id", "action", "resource_type", "resource_id", "metadata")
  VALUES (gen_random_uuid(), NEW."organisation_id", app_current_user_id(),
          'support_access.' || lower(NEW."status"::text), 'support_access', NEW."id"::text,
          jsonb_build_object('hours', NEW."hours", 'requestedBy', NEW."requested_by_user_id"));
  RETURN NULL;
END
$$;

CREATE TRIGGER "support_access_audit"
  AFTER INSERT OR UPDATE ON "support_access"
  FOR EACH ROW EXECUTE FUNCTION app_support_access_audit();

-- The only way to ask: a platform administrator, in that organisation's context.
CREATE FUNCTION app_support_request(org uuid, p_reason text, p_hours int) RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
DECLARE
  prev text := current_setting('app.organisation_id', true);
  new_id uuid := gen_random_uuid();
BEGIN
  PERFORM app_platform_require();
  IF NOT EXISTS (SELECT 1 FROM "organisations" WHERE "id" = org) THEN
    RAISE EXCEPTION 'no such organisation' USING ERRCODE = 'no_data_found';
  END IF;
  PERFORM set_config('app.organisation_id', org::text, true);
  INSERT INTO "support_access" ("id", "organisation_id", "requested_by_user_id", "reason", "hours", "updated_at")
  VALUES (new_id, org, app_current_user_id(), btrim(p_reason), p_hours, now());
  PERFORM set_config('app.organisation_id', coalesce(prev, ''), true);
  RETURN new_id;
END
$$;

ALTER TABLE "support_access" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "support_access" FORCE ROW LEVEL SECURITY;
CREATE POLICY "support_access_select" ON "support_access" FOR SELECT
  USING ("organisation_id" = app_current_organisation_id() OR "requested_by_user_id" = app_current_user_id());
CREATE POLICY "support_access_insert" ON "support_access" FOR INSERT
  WITH CHECK ("organisation_id" = app_current_organisation_id());
CREATE POLICY "support_access_update" ON "support_access" FOR UPDATE
  USING ("organisation_id" = app_current_organisation_id())
  WITH CHECK ("organisation_id" = app_current_organisation_id());

REVOKE ALL ON "support_access" FROM PUBLIC;
GRANT SELECT, UPDATE ON "support_access" TO veyra_app;
GRANT EXECUTE ON FUNCTION app_support_request(uuid, text, int) TO veyra_app;
